pub fn parse_yaml_theme(content: &str) -> Result<Theme, String> {
    let mut theme = Theme::default();
    let mut current_section = "";
    let mut current_subsection = "";

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let indent = line.len() - line.trim_start().len();

        if indent == 0 {
            if trimmed.starts_with("meta:") {
                current_section = "meta";
                current_subsection = "";
            } else if trimmed.starts_with("colors:") {
                current_section = "colors";
                current_subsection = "";
            } else if trimmed.starts_with("window_colors:") {
                current_section = "window_colors";
                current_subsection = "";
            } else if trimmed.starts_with("bar_colors:") {
                current_section = "bar_colors";
                current_subsection = "";
            }
            continue;
        }

        if current_section == "meta" {
            if let Some((k, v)) = parse_kv(trimmed) {
                match k.as_str() {
                    "name" => theme.name = clean_val(&v),
                    "description" => theme.description = clean_val(&v),
                    "author" => theme.author = clean_val(&v),
                    _ => {}
                }
            }
        } else if current_section == "colors" {
            if let Some((k, v)) = parse_kv(trimmed) {
                theme.colors.insert(k, clean_val(&v));
            }
        } else if current_section == "window_colors" {
            if indent == 2 || indent == 4 && trimmed.ends_with(':') {
                if let Some(k) = trimmed.strip_suffix(':') {
                    current_subsection = k.trim();
                }
            } else if let Some((k, v)) = parse_kv(trimmed) {
                let val = clean_val(&v);
                let target_wc = match current_subsection {
                    "focused" => theme.window_colors.focused.get_or_insert_with(|| WindowColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "focused_inactive" => theme.window_colors.focused_inactive.get_or_insert_with(|| WindowColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "unfocused" => theme.window_colors.unfocused.get_or_insert_with(|| WindowColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "urgent" => theme.window_colors.urgent.get_or_insert_with(|| WindowColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    _ => continue,
                };
                match k.as_str() {
                    "border" => target_wc.border = val,
                    "background" => target_wc.background = val,
                    "text" => target_wc.text = val,
                    "indicator" => target_wc.indicator = Some(val),
                    _ => {}
                }
            }
        } else if current_section == "bar_colors" {
            if (indent == 2 || indent == 4) && trimmed.contains(':') && !trimmed.contains("#") {
                let parts: Vec<&str> = trimmed.splitn(2, ':').collect();
                let k = parts[0].trim();
                let v = parts[1].trim();
                if v.is_empty() {
                    current_subsection = k;
                    continue;
                } else {
                    current_subsection = "";
                    let val = clean_val(v);
                    match k {
                        "background" => theme.bar_colors.background = Some(val),
                        "statusline" => theme.bar_colors.statusline = Some(val),
                        "separator" => theme.bar_colors.separator = Some(val),
                        _ => {}
                    }
                    continue;
                }
            }

            if let Some((k, v)) = parse_kv(trimmed) {
                let val = clean_val(&v);
                let target_ws = match current_subsection {
                    "focused_workspace" => theme.bar_colors.focused_workspace.get_or_insert_with(|| WorkspaceColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "active_workspace" => theme.bar_colors.active_workspace.get_or_insert_with(|| WorkspaceColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "inactive_workspace" => theme.bar_colors.inactive_workspace.get_or_insert_with(|| WorkspaceColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "urgent_workspace" => theme.bar_colors.urgent_workspace.get_or_insert_with(|| WorkspaceColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    "binding_mode" => theme.bar_colors.binding_mode.get_or_insert_with(|| WorkspaceColor {
                        border: String::new(), background: String::new(), text: String::new(), indicator: None
                    }),
                    _ => continue,
                };
                match k.as_str() {
                    "border" => target_ws.border = val,
                    "background" => target_ws.background = val,
                    "text" => target_ws.text = val,
                    "indicator" => target_ws.indicator = Some(val),
                    _ => {}
                }
            }
        }
    }

    Ok(theme)
}

fn parse_kv(line: &str) -> Option<(String, String)> {
    if let Some(idx) = line.find(':') {
        let key = line[..idx].trim().to_string();
        let val = line[idx+1..].trim().to_string();
        Some((key, val))
    } else {
        None
    }
}

fn clean_val(val: &str) -> String {
    let mut s = val.trim();
    if (s.starts_with('"') && s.ends_with('"')) || (s.starts_with('\'') && s.ends_with('\'')) {
        s = &s[1..s.len()-1];
    }
    s.to_string()
}

