    } else {
        out.push_str("\n");
        let mut print_wc = |label: &str, opt: &Option<(String, String, String, String)>| {
            if let Some((b, bg, t, ind)) = opt {
                out.push_str(&format!("  {}:\n", label));
                out.push_str(&format!("    border: {}\n", b));
                out.push_str(&format!("    background: {}\n", bg));
                out.push_str(&format!("    text: {}\n", t));
                out.push_str(&format!("    indicator: {}\n", ind));
