fn hex_to_rgb(hex_str: &str) -> Option<(u8, u8, u8)> {
    let s = hex_str.trim().trim_start_matches('#');
    if s.len() == 6 {
        let r = u8::from_str_radix(&s[0..2], 16).ok()?;
        let g = u8::from_str_radix(&s[2..4], 16).ok()?;
        let b = u8::from_str_radix(&s[4..6], 16).ok()?;
        Some((r, g, b))
    } else if s.len() == 3 {
        let r = u8::from_str_radix(&s[0..1], 16).ok()? * 17;
        let g = u8::from_str_radix(&s[1..2], 16).ok()? * 17;
        let b = u8::from_str_radix(&s[2..3], 16).ok()? * 17;
        Some((r, g, b))
    } else {
        None
    }
}

pub fn generate_theme_yaml(config_content: &str) -> String {
    let mut win_focused = None;
    let mut win_focused_inactive = None;
    let mut win_unfocused = None;
    let mut win_urgent = None;

    let mut bar_bg = None;
    let mut bar_st = None;
    let mut bar_sep = None;
    let mut bar_fw = None;
    let mut bar_uw = None;

    let mut in_bar = false;
    let mut in_bar_colors = false;

    for line in config_content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if trimmed.starts_with("bar {") || trimmed == "bar" {
            in_bar = true;
            continue;
        }
        if in_bar && (trimmed.starts_with("colors {") || trimmed == "colors") {
            in_bar_colors = true;
            continue;
        }
        if in_bar_colors && trimmed == "}" {
            in_bar_colors = false;
            continue;
        }
        if in_bar && !in_bar_colors && trimmed == "}" {
            in_bar = false;
            continue;
        }

        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }

        if in_bar_colors {
            match parts[0] {
                "background" if parts.len() >= 2 => bar_bg = Some(parts[1].to_string()),
                "statusline" if parts.len() >= 2 => bar_st = Some(parts[1].to_string()),
                "separator" if parts.len() >= 2 => bar_sep = Some(parts[1].to_string()),
                "focused_workspace" if parts.len() >= 4 => {
                    bar_fw = Some((parts[1].to_string(), parts[2].to_string(), parts[3].to_string()));
                }
                "urgent_workspace" if parts.len() >= 4 => {
                    bar_uw = Some((parts[1].to_string(), parts[2].to_string(), parts[3].to_string()));
                }
                _ => {}
            }
        } else if parts[0].starts_with("client.") {
            if parts.len() >= 5 {
                let quad = (parts[1].to_string(), parts[2].to_string(), parts[3].to_string(), parts[4].to_string());
                match parts[0] {
                    "client.focused" => win_focused = Some(quad),
                    "client.focused_inactive" => win_focused_inactive = Some(quad),
                    "client.unfocused" => win_unfocused = Some(quad),
                    "client.urgent" => win_urgent = Some(quad),
                    _ => {}
                }
            }
        }
    }

    let mut hex_to_name: HashMap<String, String> = HashMap::new();
    let mut name_counts: HashMap<String, usize> = HashMap::new();

    let mut get_color_name = |hex: &str| -> String {
        let norm_hex = if hex.starts_with('#') {
            hex.to_uppercase()
        } else {
            format!("#{}", hex.to_uppercase())
        };

        if let Some(existing) = hex_to_name.get(&norm_hex) {
            return existing.clone();
        }

        let mut base_name = "color".to_string();
        if let Some((tr, tg, tb)) = hex_to_rgb(&norm_hex) {
            let mut best_dist = u64::MAX;
            for &(name, cr, cg, cb) in CSS_COLORS {
                let dr = tr as i64 - cr as i64;
                let dg = tg as i64 - cg as i64;
                let db = tb as i64 - cb as i64;
                let d = (dr*dr + dg*dg + db*db) as u64;
                if d < best_dist {
                    best_dist = d;
                    base_name = name.to_string();
                }
            }
        }

        let count = name_counts.entry(base_name.clone()).or_insert(0);
        let final_name = if *count == 0 {
            base_name
        } else {
            format!("{}-{}", base_name, *count)
        };
        *count += 1;

        hex_to_name.insert(norm_hex, final_name.clone());
        final_name
    };

    let mut map_wc = |opt: &Option<(String, String, String, String)>| {
        opt.as_ref().map(|(b, bg, t, ind)| {
            (get_color_name(b), get_color_name(bg), get_color_name(t), get_color_name(ind))
        })
    };

    let mapped_focused = map_wc(&win_focused);
    let mapped_focused_inactive = map_wc(&win_focused_inactive);
    let mapped_unfocused = map_wc(&win_unfocused);
    let mapped_urgent = map_wc(&win_urgent);

    let mapped_bar_bg = bar_bg.as_ref().map(|s| get_color_name(s));
    let mapped_bar_st = bar_st.as_ref().map(|s| get_color_name(s));
    let mapped_bar_sep = bar_sep.as_ref().map(|s| get_color_name(s));

    let mapped_bar_fw = bar_fw.as_ref().map(|(b, bg, t)| {
        (get_color_name(b), get_color_name(bg), get_color_name(t))
    });
    let mapped_bar_uw = bar_uw.as_ref().map(|(b, bg, t)| {
        (get_color_name(b), get_color_name(bg), get_color_name(t))
    });

    let mut out = String::new();
    out.push_str("---\n");
    out.push_str("meta:\n");
    out.push_str("  description: AUTOMATICALLY GENERATED THEME\n");

    out.push_str("colors:");
    if hex_to_name.is_empty() {
        out.push_str(" {}\n");
    } else {
        out.push_str("\n");
        let mut entries: Vec<(&String, &String)> = hex_to_name.iter().collect();
        entries.sort_by_key(|&(hex, name)| (name.clone(), hex.clone()));
        for (hex, name) in entries {
            out.push_str(&format!("  {}: \"{}\"\n", name, hex));
        }
    }

    out.push_str("window_colors:");
    let has_win = mapped_focused.is_some() || mapped_focused_inactive.is_some() || mapped_unfocused.is_some() || mapped_urgent.is_some();
    if !has_win {
        out.push_str(" {}\n");
    } else {
        out.push_str("\n");
        let mut print_wc = |label: &str, opt: &Option<(String, String, String, String)>| {
            if let Some((b, bg, t, ind)) = opt {
                out.push_str(&format!("  {}:\n", label));
                out.push_str(&format!("    border: {}\n", b));
                out.push_str(&format!("    background: {}\n", bg));
                out.push_str(&format!("    text: {}\n", t));
                out.push_str(&format!("    indicator: {}\n", ind));
            }
        };
        print_wc("focused", &mapped_focused);
        print_wc("focused_inactive", &mapped_focused_inactive);
        print_wc("unfocused", &mapped_unfocused);
        print_wc("urgent", &mapped_urgent);
    }

    out.push_str("bar_colors:");
    let has_bar = mapped_bar_bg.is_some() || mapped_bar_st.is_some() || mapped_bar_sep.is_some() || mapped_bar_fw.is_some() || mapped_bar_uw.is_some();
    if !has_bar {
        out.push_str(" {}\n");
    } else {
        out.push_str("\n");
        if let Some(s) = &mapped_bar_bg {
            out.push_str(&format!("  background: {}\n", s));
