            } else {
                insert_colors_block(&mut lines, bar_start, bar_end, theme);
            }
        }
        i += 1;
    }

    // Append missing client lines at end
    for client_line in to_append_client {
        lines.push(client_line);
    }

    let mut result = lines.join("\n");
    if config_content.ends_with('\n') && !result.ends_with('\n') {
        result.push('\n');
    } else if !result.ends_with('\n') {
        result.push('\n');
    }
    result
}

fn format_workspace(key: &str, ws: &WorkspaceColor, theme: &Theme) -> String {
    let b = theme.resolve(&ws.border);
    let bg = theme.resolve(&ws.background);
    let t = theme.resolve(&ws.text);
    let ind = ws.indicator.as_ref().map(|s| theme.resolve(s));

    let mut line = format!("{} {} {} {} ", key, b, bg, t);
    if let Some(i) = ind {
        line.push_str(&format!(" {}", i));
    }
    line
}

fn update_existing_colors_block(lines: &mut Vec<String>, colors_start: usize, colors_end: usize, theme: &Theme) {
    let mut used_keys = std::collections::HashSet::new();

    let mut j = colors_start + 1;
    while j < colors_end {
        let trimmed = lines[j].trim().to_string();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            j += 1;
            continue;
        }

        let first_word = trimmed.split_whitespace().next().unwrap_or("");
        let indent = lines[j].len() - lines[j].trim_start().len();
        let pad = " ".repeat(indent);

        match first_word {
            "background" => {
                if let Some(ref val) = theme.bar_colors.background {
                    lines[j] = format!("{}background {}", pad, theme.resolve(val));
                    used_keys.insert("background");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "statusline" => {
                if let Some(ref val) = theme.bar_colors.statusline {
                    lines[j] = format!("{}statusline {}", pad, theme.resolve(val));
                    used_keys.insert("statusline");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "separator" => {
                if let Some(ref val) = theme.bar_colors.separator {
                    lines[j] = format!("{}separator {}", pad, theme.resolve(val));
                    used_keys.insert("separator");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "focused_workspace" => {
                if let Some(ref ws) = theme.bar_colors.focused_workspace {
                    lines[j] = format!("{}{}", pad, format_workspace("focused_workspace", ws, theme));
                    used_keys.insert("focused_workspace");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "active_workspace" => {
                if let Some(ref ws) = theme.bar_colors.active_workspace {
                    lines[j] = format!("{}{}", pad, format_workspace("active_workspace", ws, theme));
                    used_keys.insert("active_workspace");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "inactive_workspace" => {
                if let Some(ref ws) = theme.bar_colors.inactive_workspace {
                    lines[j] = format!("{}{}", pad, format_workspace("inactive_workspace", ws, theme));
                    used_keys.insert("inactive_workspace");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "urgent_workspace" => {
                if let Some(ref ws) = theme.bar_colors.urgent_workspace {
                    lines[j] = format!("{}{}", pad, format_workspace("urgent_workspace", ws, theme));
                    used_keys.insert("urgent_workspace");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            "binding_mode" => {
                if let Some(ref ws) = theme.bar_colors.binding_mode {
                    lines[j] = format!("{}{}", pad, format_workspace("binding_mode", ws, theme));
                    used_keys.insert("binding_mode");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            _ => {
                lines.remove(j);
            }
        }
    }

    let indent_colors = lines[colors_start].len() - lines[colors_start].trim_start().len();
    let pad = " ".repeat(indent_colors + 2);

    let mut new_lines = Vec::new();

    let bar_keys = [
        ("background", theme.bar_colors.background.as_ref().map(|v| format!("background {}", theme.resolve(v)))),
        ("statusline", theme.bar_colors.statusline.as_ref().map(|v| format!("statusline {}", theme.resolve(v)))),
        ("separator", theme.bar_colors.separator.as_ref().map(|v| format!("separator {}", theme.resolve(v)))),
        ("focused_workspace", theme.bar_colors.focused_workspace.as_ref().map(|ws| format_workspace("focused_workspace", ws, theme))),
        ("active_workspace", theme.bar_colors.active_workspace.as_ref().map(|ws| format_workspace("active_workspace", ws, theme))),
        ("inactive_workspace", theme.bar_colors.inactive_workspace.as_ref().map(|ws| format_workspace("inactive_workspace", ws, theme))),
        ("urgent_workspace", theme.bar_colors.urgent_workspace.as_ref().map(|ws| format_workspace("urgent_workspace", ws, theme))),
        ("binding_mode", theme.bar_colors.binding_mode.as_ref().map(|ws| format_workspace("binding_mode", ws, theme))),
    ];

    for (k, opt_str) in &bar_keys {
        if !used_keys.contains(k) {
            if let Some(s) = opt_str {
                new_lines.push(format!("{}{}", pad, s));
            }
        }
    }

    let insert_pos = colors_end;
    for (idx, nl) in new_lines.into_iter().enumerate() {
        lines.insert(insert_pos + idx, nl);
    }
}

fn insert_colors_block(lines: &mut Vec<String>, bar_start: usize, bar_end: usize, theme: &Theme) {
    let bar_indent = lines[bar_start].len() - lines[bar_start].trim_start().len();
    let pad1 = " ".repeat(bar_indent + 2);
    let pad2 = " ".repeat(bar_indent + 4);

    let mut new_block = Vec::new();
    new_block.push(format!("{}colors {{", pad1));

    if let Some(ref v) = theme.bar_colors.separator {
        new_block.push(format!("{}separator {}", pad2, theme.resolve(v)));
    }
    if let Some(ref v) = theme.bar_colors.background {
        new_block.push(format!("{}background {}", pad2, theme.resolve(v)));
    }
    if let Some(ref v) = theme.bar_colors.statusline {
        new_block.push(format!("{}statusline {}", pad2, theme.resolve(v)));
    }
    if let Some(ref ws) = theme.bar_colors.focused_workspace {
        new_block.push(format!("{}{}", pad2, format_workspace("focused_workspace", ws, theme)));
    }
    if let Some(ref ws) = theme.bar_colors.active_workspace {
        new_block.push(format!("{}{}", pad2, format_workspace("active_workspace", ws, theme)));
    }
    if let Some(ref ws) = theme.bar_colors.inactive_workspace {
        new_block.push(format!("{}{}", pad2, format_workspace("inactive_workspace", ws, theme)));
    }
    if let Some(ref ws) = theme.bar_colors.urgent_workspace {
        new_block.push(format!("{}{}", pad2, format_workspace("urgent_workspace", ws, theme)));
    }
    if let Some(ref ws) = theme.bar_colors.binding_mode {
        new_block.push(format!("{}{}", pad2, format_workspace("binding_mode", ws, theme)));
    }

    new_block.push(format!("{}}}", pad1));

    let insert_pos = bar_end;
    for (idx, nl) in new_block.into_iter().enumerate() {
        lines.insert(insert_pos + idx, nl);
    }
}
