                if i + 1 < args.len() {
                    to_theme_opt = Some(args[i + 1].clone());
                    i += 1;
                } else {
                    to_theme_opt = Some(String::new());
                }
            }
            _ => {
                if arg.starts_with('-') {
                    // Unknown flag or option
                } else if theme_arg.is_none() {
                    theme_arg = Some(arg.clone());
                }
            }
        }
        i += 1;
