            let yaml = generate_theme_yaml(&content);
            print!("{}", yaml);
            exit(0);
        }
    }

    let theme_str = match theme_arg {
        Some(t) => t,
        None => {
            print_usage_error(prog_name);
            exit(1);
        }
    };

    // Resolve Theme
    let theme: Theme = if let Some(builtin) = get_builtin_theme(&theme_str) {
        builtin
    } else {
        match fs::read_to_string(&theme_str) {
            Ok(content) => {
                match parse_yaml_theme(&content) {
                    Ok(t) => t,
                    Err(e) => {
                        panic!("Could not parse yaml for theme: {}", e);
                    }
                }
            }
            Err(e) => {
                eprintln!("Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.", theme_str, e);
                exit(1);
            }
        }
    };

    // Find config path
    let config_path = if let Some(p) = config_path_opt {
        p
    } else {
        let home = env::var("HOME").unwrap_or_default();
        let dot_i3 = PathBuf::from(&home).join(".i3").join("config");
        let dot_config = PathBuf::from(&home).join(".config").join("i3").join("config");

        if dot_i3.exists() {
            dot_i3.to_string_lossy().to_string()
        } else if dot_config.exists() {
            dot_config.to_string_lossy().to_string()
        } else {
            eprintln!("Could not find i3 config");
            exit(1);
        }
    };

