    match Command::new("i3").args(&["-C", "-c", &config_path]).status() {
        Ok(status) => {
            if !status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", config_path);
                exit(1);
            }
        }
        Err(e) => {
            eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, e);
            exit(1);
        }
    }

    // Determine output destination
    let target_output = if let Some(out_p) = output_path_opt {
        Some(out_p)
    } else if save {
        Some(config_path.clone())
    } else {
        None
    };

    let rand_id = generate_rand_u32();

    if let Some(_) = &target_output {
        let backup_dir = format!("/tmp/i3-style/{}", rand_id);
        let _ = fs::create_dir_all(&backup_dir);
        let backup_input = format!("{}/config-input", backup_dir);
        let _ = fs::copy(&config_path, &backup_input);
        eprintln!("saving config at {} to /tmp/i3-style/{}/config-input", config_path, rand_id);
    }

