            "-l" | "--list-all" => list_all = true,
            "-r" | "--reload" => reload = true,
            "-s" | "--save" => save = true,
            "-c" | "--config" => {
                if i + 1 < args.len() {
                    config_path_opt = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-o" | "--output" => {
                if i + 1 < args.len() {
                    output_path_opt = Some(args[i + 1].clone());
                    i += 1;
                }
            }
            "-t" | "--to-theme" => {
                if i + 1 < args.len() {
                    to_theme_opt = Some(args[i + 1].clone());
                    i += 1;
                } else {
                    to_theme_opt = Some(String::new());
                }
            }
            _ => {
                if arg.starts_with('-') {
                    // Unknown flag or option
                } else if theme_arg.is_none() {
                    theme_arg = Some(arg.clone());
                }
            }
        }
        i += 1;
    }

    if help {
        print_help(prog_name);
        exit(0);
    }

    if version {
        println!("i3-style 1.0");
        exit(0);
    }

    if list_all {
        theme::list_all_themes();
        exit(0);
    }

    if let Some(ref to_theme_path) = to_theme_opt {
        if !to_theme_path.is_empty() {
            // Panic matching src/theme.rs:613:40 if file not found
            let content = fs::read_to_string(to_theme_path).unwrap();
            let yaml = generate_theme_yaml(&content);
            print!("{}", yaml);
            exit(0);
        }
    }

    let theme_str = match theme_arg {
        Some(t) => t,
        None => {
            print_usage_error(prog_name);
            exit(1);
        }
    };

    // Resolve Theme
    let theme: Theme = if let Some(builtin) = get_builtin_theme(&theme_str) {
        builtin
    } else {
        match fs::read_to_string(&theme_str) {
            Ok(content) => {
                match parse_yaml_theme(&content) {
                    Ok(t) => t,
                    Err(e) => {
                        panic!("Could not parse yaml for theme: {}", e);
                    }
                }
            }
            Err(e) => {
                eprintln!("Could not open theme: {} - {}\n Use `i3-style --list-all` to see the available themes.", theme_str, e);
                exit(1);
            }
        }
    };

    // Find config path
    let config_path = if let Some(p) = config_path_opt {
        p
    } else {
        let home = env::var("HOME").unwrap_or_default();
        let dot_i3 = PathBuf::from(&home).join(".i3").join("config");
        let dot_config = PathBuf::from(&home).join(".config").join("i3").join("config");

        if dot_i3.exists() {
            dot_i3.to_string_lossy().to_string()
        } else if dot_config.exists() {
            dot_config.to_string_lossy().to_string()
        } else {
            eprintln!("Could not find i3 config");
            exit(1);
        }
    };

    // Validate original config
    match Command::new("i3").args(&["-C", "-c", &config_path]).status() {
        Ok(status) => {
            if !status.success() {
                eprintln!("Could not validate config.\nUse `i3 -C -c {}` to see validation errors.", config_path);
                exit(1);
            }
        }
        Err(e) => {
            eprintln!("Could not validate config with `i3 -C -c {}` (is i3 in the PATH?) {}", config_path, e);
            exit(1);
        }
    }

    // Determine output destination
    let target_output = if let Some(out_p) = output_path_opt {
        Some(out_p)
    } else if save {
        Some(config_path.clone())
    } else {
        None
    };

    let rand_id = generate_rand_u32();

    if let Some(_) = &target_output {
        let backup_dir = format!("/tmp/i3-style/{}", rand_id);
        let _ = fs::create_dir_all(&backup_dir);
        let backup_input = format!("{}/config-input", backup_dir);
        let _ = fs::copy(&config_path, &backup_input);
        eprintln!("saving config at {} to /tmp/i3-style/{}/config-input", config_path, rand_id);
    }

    // Panic matching src/writer.rs:24:40 if file fails to read
    let content = fs::read_to_string(&config_path).unwrap();
    let new_content = update_config(&content, &theme);

    if let Some(ref out_p) = target_output {
        let backup_output = format!("/tmp/i3-style/{}/config-output", rand_id);
        let _ = fs::write(&backup_output, &new_content);
        let _ = fs::write(out_p, &new_content);
    } else {
        print!("{}", new_content);
    }

    if reload {
        if let Err(e) = Command::new("i3-msg").arg("reload").status() {
            eprintln!("Could not reload config with i3-msg: {}", e);
            exit(1);
        }
    }
}

fn print_help(prog_name: &str) {
    println!("i3-style 1.0");
    println!("Make your i3 config a bit more stylish");
    println!();
    println!("USAGE:");
    println!("    {} [FLAGS] [OPTIONS] [theme]", prog_name);
    println!();
    println!("FLAGS:");
    println!("    -h, --help        Prints help information");
    println!("    -l, --list-all    Print a list of all available themes");
    println!("    -r, --reload      Apply the theme by reloading the config");
    println!("    -s, --save        Set the output file to the path of the input file");
    println!("    -V, --version     Prints version information");
    println!();
    println!("OPTIONS:");
    println!("    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.");
    println!("    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>");
    println!("    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others");
    println!("                             [default: ]");
    println!();
    println!("ARGS:");
    println!("    <theme>    The theme to use");
}

fn print_usage_error(prog_name: &str) {
    println!("USAGE:");
    println!("    {} [FLAGS] [OPTIONS] [theme]", prog_name);
    println!();
    println!("Select a theme as the first argument. Use `--list-all` to see the themes.");
}

fn generate_rand_u32() -> u32 {
    use std::collections::hash_map::RandomState;
    use std::hash::{BuildHasher, Hasher};
    use std::time::SystemTime;

    let s = RandomState::new();
    let mut hasher = s.build_hasher();
    hasher.write_u128(SystemTime::now().duration_since(SystemTime::UNIX_EPOCH).unwrap_or_default().as_nanos());
    hasher.finish() as u32
}
