use crate::theme::{Theme, WorkspaceColor};

pub fn update_config(config_content: &str, theme: &Theme) -> String {
    let mut lines: Vec<String> = config_content.lines().map(|s| s.to_string()).collect();

    // 1. Process client.* lines
    let client_classes = [
        ("focused", &theme.window_colors.focused),
        ("focused_inactive", &theme.window_colors.focused_inactive),
        ("unfocused", &theme.window_colors.unfocused),
        ("urgent", &theme.window_colors.urgent),
    ];

    let mut to_append_client = Vec::new();

    for (class_name, opt_wc) in &client_classes {
        if let Some(wc) = opt_wc {
            let b = theme.resolve(&wc.border);
            let bg = theme.resolve(&wc.background);
            let t = theme.resolve(&wc.text);
            let ind = wc.indicator.as_ref().map(|s| theme.resolve(s));

            let formatted = match ind {
                Some(i) => format!("client.{} {} {} {} {}", class_name, b, bg, t, i),
                None => format!("client.{} {} {} {}", class_name, b, bg, t),
            };

            let prefix = format!("client.{}", class_name);
            let mut found = false;
            for line in lines.iter_mut() {
                let trimmed = line.trim();
                if trimmed.starts_with(&prefix) {
                    if let Some(c) = trimmed.chars().nth(prefix.len()) {
                        if !c.is_whitespace() {
                            continue;
                        }
                    }
                    *line = formatted.clone();
                    found = true;
                }
            }
            if !found {
                to_append_client.push(formatted);
            }
        }
    }

    // 2. Process bar blocks
    let mut i = 0;
    while i < lines.len() {
        let trimmed = lines[i].trim();
        if trimmed.starts_with("bar {") || trimmed == "bar" {
            let bar_start = i;
            let mut bar_end = i;
            let mut depth = 0;
            let mut has_colors = false;
            let mut colors_start = 0;
            let mut colors_end = 0;

            for j in bar_start..lines.len() {
                let line_j = &lines[j];
                let trim_j = line_j.trim();
                if trim_j.starts_with('#') {
                    continue;
                }
                for c in trim_j.chars() {
                    if c == '{' {
                        depth += 1;
                    } else if c == '}' {
                        depth -= 1;
                    }
                }
                if (trim_j.starts_with("colors {") || trim_j == "colors") && depth >= 1 {
                    has_colors = true;
                    colors_start = j;
                }
                if has_colors && colors_end == 0 && depth == 1 && trim_j == "}" {
                    colors_end = j;
                }
                if depth == 0 {
                    bar_end = j;
                    break;
                }
            }

            if has_colors {
                update_existing_colors_block(&mut lines, colors_start, colors_end, theme);
            } else {
                insert_colors_block(&mut lines, bar_start, bar_end, theme);
            }
        }
        i += 1;
    }

    // Append missing client lines at end
    for client_line in to_append_client {
        lines.push(client_line);
    }

