                    lines[j] = format!("{}{}", pad, format_workspace("binding_mode", ws, theme, true));
                    used_keys.insert("binding_mode");
                    j += 1;
                } else {
                    lines.remove(j);
                }
            }
            _ => {
                lines.remove(j);
            }
        }
    }

    let indent_colors = lines[colors_start].len() - lines[colors_start].trim_start().len();
    let pad = " ".repeat(indent_colors + 2);

    let mut new_lines = Vec::new();

    let bar_keys = [
        ("separator", theme.bar_colors.separator.as_ref().map(|v| format!("separator {}", theme.resolve(v)))),
        ("background", theme.bar_colors.background.as_ref().map(|v| format!("background {}", theme.resolve(v)))),
        ("statusline", theme.bar_colors.statusline.as_ref().map(|v| format!("statusline {}", theme.resolve(v)))),
        ("focused_workspace", theme.bar_colors.focused_workspace.as_ref().map(|ws| format_workspace("focused_workspace", ws, theme, false))),
        ("active_workspace", theme.bar_colors.active_workspace.as_ref().map(|ws| format_workspace("active_workspace", ws, theme, false))),
        ("inactive_workspace", theme.bar_colors.inactive_workspace.as_ref().map(|ws| format_workspace("inactive_workspace", ws, theme, false))),
        ("urgent_workspace", theme.bar_colors.urgent_workspace.as_ref().map(|ws| format_workspace("urgent_workspace", ws, theme, false))),
        ("binding_mode", theme.bar_colors.binding_mode.as_ref().map(|ws| format_workspace("binding_mode", ws, theme, false))),
    ];

    for (k, opt_str) in &bar_keys {
        if !used_keys.contains(k) {
            if let Some(s) = opt_str {
                new_lines.push(format!("{}{}", pad, s));
            }
        }
    }

    let insert_pos = colors_end;
    for (idx, nl) in new_lines.into_iter().enumerate() {
        lines.insert(insert_pos + idx, nl);
    }
}

fn insert_colors_block(lines: &mut Vec<String>, bar_start: usize, bar_end: usize, theme: &Theme) {
    let bar_indent = lines[bar_start].len() - lines[bar_start].trim_start().len();
